use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path,collections::BTreeMap};
const R:&str="/home/ubuntu/src/zopro-perf-work/control-codegen175";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn main(){let root=Path::new(R);assert!(!root.join("function-differences.json").exists());let audit=read(root.join("analysis.json"));let mut ranges=BTreeMap::new();let mut text=BTreeMap::new();let mut bases=BTreeMap::new();for v in["accepted","combined_OFF"]{let c=&audit["variants"][v];let bytes=fs::read(c["binary"].as_str().unwrap()).unwrap();assert_eq!(format!("{:x}",Sha256::digest(&bytes)),c["ELF_sha256"]);let raw=read(root.join(format!("{v}-demangled.json")));let mut names=BTreeMap::<String,Vec<(u64,u64,String)>>::new();for(raw,c)in raw.as_object().unwrap(){names.entry(c["name"].as_str().unwrap().into()).or_default().push((u64::from_str_radix(c["address_hex"].as_str().unwrap(),16).unwrap(),c["size"].as_u64().unwrap(),raw.clone()));}for r in names.values_mut(){r.sort();}ranges.insert(v,names);let sections=fs::read_to_string(root.join(format!("{v}-sections.txt"))).unwrap();let fields=sections.lines().find(|l|l.split_whitespace().any(|w|w==".text")).unwrap().split_whitespace().collect::<Vec<_>>();let i=fields.iter().position(|&f|f==".text").unwrap();bases.insert(v,u64::from_str_radix(fields[i+2],16).unwrap());let offset=c["text_offset"].as_u64().unwrap()as usize;let size=c["text_bytes"].as_u64().unwrap()as usize;text.insert(v,bytes[offset..offset+size].to_vec());}
let mut changed=Vec::new();let mut ambiguous=Vec::new();let mut equal_bytes=0;let mut equal_ranges=0;let mut changed_raw=0;for(name,aa)in &ranges["accepted"]{let bb=&ranges["combined_OFF"][name];if aa.iter().map(|a|(a.0,a.1)).collect::<Vec<_>>()==bb.iter().map(|a|(a.0,a.1)).collect::<Vec<_>>(){equal_ranges+=1;}if aa.len()!=1||bb.len()!=1{ambiguous.push(json!({"name":name,"accepted":aa,"OFF":bb}));continue}let a=&aa[0];let b=&bb[0];if a.2!=b.2{changed_raw+=1;}assert_eq!(a.1,b.1);let ai=(a.0-bases["accepted"])as usize;let bi=(b.0-bases["combined_OFF"])as usize;let len=a.1 as usize;let av=&text["accepted"][ai..ai+len];let bv=&text["combined_OFF"][bi..bi+len];if av==bv{equal_bytes+=1;}else{changed.push(json!({"name":name,"accepted_symbol":a.2,"OFF_symbol":b.2,"accepted_address":a.0,"OFF_address":b.0,"length":len,"different_bytes":av.iter().zip(bv).filter(|(a,b)|a!=b).count()}));}}
let result=json!({"matched_unique_demangled_names":ranges["accepted"].len()-ambiguous.len(),"exact_address_size_multiset_names":equal_ranges,"unique_functions_exact_bytes":equal_bytes,"unique_functions_different_raw_symbol":changed_raw,"unique_functions_different_bytes":changed,"ambiguous_names":ambiguous,"static_only":true,"no_runtime_equivalence_or_causality_claim":true,"prior_raw_symbol_mismatches_include_missing_hash_changed_names":true});fs::write(root.join("function-differences.json"),serde_json::to_vec_pretty(&result).unwrap()).unwrap();println!("Names{} exactaddressranges{equal_ranges}; uniqueexactbytes{equal_bytes};uniquedifferentbytes{};ambiguous{};hashchanged{changed_raw}",ranges["accepted"].len(),result["unique_functions_different_bytes"].as_array().unwrap().len(),result["ambiguous_names"].as_array().unwrap().len());
}
